4257	/// ADR-0020 §6's independence, checked rather than assumed (M17.5 F-27 / P1-A07).
4258	///
4259	/// The runner records `reviewer.model_family`, `reviewer.backend` and an
4260	/// identity hash precisely so independence is auditable. The qualification
4261	/// verifier never looked at any of them — this session BUILT that evidence and
4262	/// then failed to check it, which is the same mistake as trusting a status
4263	/// string. Two reviews from one family satisfy every other check in this file.
4264	fn verify_reviewer_independence(records: &[(String, ReviewRecord)]) -> Result<()> {
4265	    // M17.5 Stage 3: `< 2` -> `> 2` survives here and is EQUIVALENT, not
4266	    // untested. With fewer than two records the loop below builds sets of size
4267	    // `records.len()`, and `distinct != records.len()` is then false, so the
4268	    // function returns Ok either way. The early return states the intent —
4269	    // independence is a claim about a PAIR — and costs nothing.
4270	    if records.is_empty() {
4271	        return Ok(());
4272	    }
4273	    anyhow::ensure!(
4274	        records.len() == 2,
4275	        "blind review evidence must contain exactly two records"
4276	    );
4277	    let passes = records
4278	        .iter()
4279	        .map(|(_, record)| record.pass)
4280	        .collect::<BTreeSet<_>>();
4281	    anyhow::ensure!(
4282	        passes == BTreeSet::from([1, 2]),
4283	        "blind review records must have exactly pass ordinals 1 and 2"
4284	    );
4285	    let mut families: BTreeSet<&str> = BTreeSet::new();
4286	    let mut backends: BTreeSet<&str> = BTreeSet::new();
4287	    let mut identities: BTreeSet<&str> = BTreeSet::new();
4288	    let mut prompts: BTreeSet<&str> = BTreeSet::new();
4289	    let mut sessions: BTreeSet<&str> = BTreeSet::new();
4290	    for (who, record) in records {
4291	        if record.reviewer.model_family.trim().is_empty() {
4292	            anyhow::bail!("{who}: record names no model family");
4293	        }
4294	        if record.reviewer.identity_hash.trim().is_empty() {
4295	            anyhow::bail!("{who}: record carries no reviewer identity hash");
4296	        }
4297	        require_hex_digest(
4298	            &format!("{who} reviewer identity_hash"),
4299	            &record.reviewer.identity_hash,
4300	        )?;
4301	        require_hex_digest(
4302	            &format!("{who} sanitized_prompt_hash"),
4303	            &record.sanitized_prompt_hash,
4304	        )?;
4305	        require_hex_digest(
4306	            &format!("{who} isolated_session_hash"),
4307	            &record.isolated_session_hash,
4308	        )?;
4309	        families.insert(record.reviewer.model_family.as_str());
4310	        backends.insert(record.reviewer.backend.as_str());
4311	        identities.insert(record.reviewer.identity_hash.as_str());
4312	        prompts.insert(record.sanitized_prompt_hash.as_str());
4313	        sessions.insert(record.isolated_session_hash.as_str());
4314	    }
4315	    for (label, distinct) in [
4316	        ("model families", families.len()),
4317	        ("backends", backends.len()),
4318	        ("reviewer identities", identities.len()),
4319	        ("sanitized prompts", prompts.len()),
4320	        ("isolated sessions", sessions.len()),
4321	    ] {
4322	        if distinct != records.len() {
4323	            anyhow::bail!(
4324	                "{} reviews share {label} ({distinct} distinct across {} reviews); \
4325	                 ADR-0020 §6 requires distinct model families with isolated state",
4326	                records.len(),
4327	                records.len()
4328	            );
4329	        }
4330	    }
4331	    Ok(())
4332	}
