4233	fn diff_contains_added_line(diff: &str, target_line: usize) -> bool {
4234	    diff.lines()
4235	        .filter(|line| line.starts_with("@@ "))
4236	        .any(|header| {
4237	            let Some(range) = header
4238	                .split_whitespace()
4239	                .find(|token| token.starts_with('+'))
4240	                .and_then(|token| token.strip_prefix('+'))
4241	            else {
4242	                return false;
4243	            };
4244	            let (start, count) = range
4245	                .split_once(',')
4246	                .map_or((range, "1"), |(start, count)| (start, count));
4247	            let Ok(start) = start.parse::<usize>() else {
4248	                return false;
4249	            };
4250	            let Ok(count) = count.parse::<usize>() else {
4251	                return false;
4252	            };
4253	            count > 0 && target_line >= start && target_line.saturating_sub(start) < count
4254	        })
4255	}
