4538	fn verify_mutant_killing_tests(root: &Utf8Path, packet: &Packet) -> Result<()> {
4539	    // AM-17.10: the column is derived for every mutant, whatever its
4540	    // disposition, and is checked before the clauses that inspect only killed
4541	    // ones. This function used to return here when nothing was killed, so at
4542	    // stage 1a — where all 65 mutants are predeclared — it read nothing at
4543	    // all, and a generated killer column rode through fourteen lanes.
4544	    let killed: Vec<&Mutant> = packet
4545	        .mutants
4546	        .iter()
4547	        .filter(|mutant| mutant.disposition == "killed")
4548	        .collect();
4549	    let by_id: BTreeMap<&str, &Test> = packet
4550	        .tests
4551	        .iter()
4552	        .map(|test| (test.id.as_str(), test))
4553	        .collect();
4554	    let ignored = ignored_test_names(root);
4555	    for mutant in killed {
4556	        if mutant.killing_tests.is_empty() {
4557	            anyhow::bail!("{} claims killed but names no killing test", mutant.id);
4558	        }
4559	        for test_id in &mutant.killing_tests {
4560	            let test = by_id.get(test_id.as_str()).with_context(|| {
4561	                format!(
4562	                    "{} names killing test {test_id}, which the packet does not declare",
4563	                    mutant.id
4564	                )
4565	            })?;
4566	            let leaf = test.name.rsplit("::").next().unwrap_or(test.name.as_str());
4567	            if ignored.contains(leaf) {
4568	                anyhow::bail!(
4569	                    "{} claims killed by {} ({}), which is #[ignore]d — an ignored test \
4570	                     never runs, so it cannot witness a kill",
4571	                    mutant.id,
4572	                    test_id,
4573	                    test.name
4574	                );
4575	            }
4576	        }
4577	    }
4578	    // AM-17.10: every mutant's column is derived, whatever its disposition.
4579	    // Checked last so a kill witnessed by an ignored or missing test reports
4580	    // that, rather than being answered by the derivation. The clauses above
4581	    // inspect only `killed` mutants, which is why a plan of 65 predeclared
4582	    // mutants carried a generated killer column through fourteen lanes with
4583	    // no gate reading it at all.
4584	    for mutant in &packet.mutants {
4585	        let derived = derive_killing_tests(packet, mutant)?;
4586	        anyhow::ensure!(
4587	            mutant.killing_tests == derived,
4588	            "{} names killing tests {:?}; AM-17.10 derives {:?} from requirement {} and \
4589	             operator {:?}",
4590	            mutant.id,
4591	            mutant.killing_tests,
4592	            derived,
4593	            mutant.requirement,
4594	            mutant.operator
4595	        );
4596	    }
4597	    Ok(())
4598	}
