4334	/// Every declared test name must name a test that EXISTS (M17.5 pass-2 #11).
4335	///
4336	/// `Test.name` was carried as an opaque string and never checked, so renaming a
4337	/// row to `does_not_exist` changed nothing — the traceability matrix could name
4338	/// 38 tests none of which were real.
4339	///
4340	/// This runs only at the QUALIFIED layer, not the inventory layer, and that
4341	/// asymmetry is deliberate: the proposed packet legitimately predeclares tests
4342	/// that milestones M19–M24 have not yet written, which is the whole point of an
4343	/// inventory. But a packet claiming `qualification_state: complete` while
4344	/// naming a test nobody wrote is exactly the false green this gate exists to
4345	/// stop.
4346	/// The declared stage must match what the packet actually claims (ADR-0021).
4347	///
4348	/// HAQP-1 is evaluated in two stages because ADR-0020 §3 assumed the suite it
4349	/// mutates already exists, and for Phase 1 it does not (F-28). Stage `1a` is
4350	/// everything provable before Phase 1 authorization; `1b` adds the mutation
4351	/// requirement at M24.
4352	///
4353	/// Both directions are errors. A `1a` packet claiming kills would smuggle the
4354	/// deferred requirement back in as an unwitnessed assertion — the exact thing
4355	/// the deferral exists to prevent. A `1b` packet without kills would claim the
4356	/// stronger stage while supplying the weaker evidence.
4357	fn verify_qualification_stage(packet: &Packet) -> Result<()> {
4358	    let claims_resolved = packet
4359	        .mutants
4360	        .iter()
4361	        .any(|mutant| mutant.disposition != "predeclared");
4362	    match packet.qualification_stage.as_str() {
4363	        "1a" if claims_resolved => anyhow::bail!(
4364	            "packet declares stage 1a but claims evaluated mutants; ADR-0021 defers the \
4365	             mutation requirement to 1b at M24, when the runner can produce evidence"
4366	        ),
4367	        "1b" if !claims_resolved => anyhow::bail!(
4368	            "packet declares stage 1b, which carries ADR-0020 §3's mutation \
4369	             requirement, but no mutant is killed or otherwise evaluated"
4370	        ),
4371	        "1a" | "1b" => Ok(()),
4372	        other => anyhow::bail!("unknown qualification stage {other:?}; expected 1a or 1b"),
4373	    }
4374	}
