4401	    ("missing-enum-dispatch", "malformed"),
4402	    ("oracle-short-circuit", "positive"),
4403	    ("ordering-nondeterminism", "replay"),
4404	    ("predicate-deletion", "positive"),
4405	    ("predicate-inversion", "negative"),
4406	    ("skipped-durable-transition", "recovery"),
4407	    ("stale-basis-acceptance", "basis"),
4408	    ("success-error-substitution", "negative"),
