4414	/// The killing tests AM-17.10 derives for `mutant`: the candidates are the
4415	/// tests the packet maps to its requirement, in packet order; the primary is
4500	/// this campaign wrote. Answered from `git blame`, so the classification that
4501	/// decides whether a finding is fixed or recorded is evidence rather than the
4502	/// qualifier's judgement about its own work.
4503	pub fn coordinate_is_campaign_churn(root: &Utf8Path, coordinate: &str) -> Result<bool> {
4504	    let (file, line) = coordinate
4505	        .rsplit_once(':')
4506	        .with_context(|| format!("{coordinate:?} is not a file:line coordinate"))?;
4507	    let line: u32 = line
4508	        .parse()
4509	        .with_context(|| format!("{coordinate:?} does not name a line"))?;
4510	    anyhow::ensure!(line > 0, "{coordinate:?} names line zero");
4511	    let blamed = git_text(
4512	        root,
4513	        &[
4514	            "blame",
4515	            "--porcelain",
4516	            "-L",
4517	            &format!("{line},{line}"),
4518	            "--",
4519	            file,
4520	        ],
4521	    )
4522	    .with_context(|| format!("blame {coordinate}"))?;
4523	    let commit = blamed
4524	        .split_whitespace()
4525	        .next()
4526	        .with_context(|| format!("{coordinate}: blame named no commit"))?;
4527	    // `merge-base --is-ancestor A B` succeeds when A is an ancestor of B. The
4528	    // campaign's first lane being an ancestor of the blamed commit means the
4529	    // line was written during the campaign.
4530	    let status = Command::new("git")
4531	        .current_dir(root)
4532	        .args(["merge-base", "--is-ancestor", CAMPAIGN_FIRST_LANE, commit])
4533	        .status()
4534	        .context("git merge-base --is-ancestor")?;
4535	    Ok(status.success())
4536	}
