4724	#[allow(
4725	    clippy::too_many_lines,
4726	    reason = "mutation evidence gate keeps all row invariants together"
4727	)]
4728	fn verify_mutant_evidence_row(
4729	    row: &MutantEvidenceRow,
4730	    declared: &BTreeMap<&str, &Mutant>,
4731	    seen: &mut BTreeSet<String>,
4732	    evaluated: &mut BTreeSet<String>,
4733	) -> Result<()> {
4734	    anyhow::ensure!(
4735	        seen.insert(row.id.clone()),
4736	        "duplicate mutant evidence row {}",
4737	        row.id
4738	    );
4739	    let mutant = declared
4740	        .get(row.id.as_str())
4741	        .with_context(|| format!("mutant evidence names undeclared {}", row.id))?;
4742	    // Stage 1a (M17.5 F-41). `haq mutants` records every mutant as `not-ready`
4743	    // -- "recorded, not claimed" -- and this verifier, written for 1b's
