8940	/// `haqp_flip_packet.py` had it, its local copy in `haqp_blind_review.py` had
8941	/// it, and it came back here in new code written by someone who knew about both.
8942	/// Trimming first and splitting on the status field is immune to it.
8943	fn porcelain_path(line: &str) -> Option<String> {
8944	    let (_status, rest) = line.trim_start().split_once(' ')?;
8945	    let path = rest.trim();
8946	    // Rename and copy entries read "old -> new"; the destination is what is
8947	    // present in the working tree.
8948	    let path = path.rsplit(" -> ").next().unwrap_or(path);
8949	    // Paths containing spaces or non-ASCII come back quoted; the quotes are not
8950	    // part of the path.
8951	    let path = path.trim_matches('"');
8952	    (!path.is_empty()).then(|| path.to_owned())
8953	}
