8955	/// Read one evidence artifact, transparently decompressing `.zst`.
8956	///
8957	/// A full 30-minute ASan campaign emits gigabytes of strace output — the
8958	/// 2026-09-02 run produced a 1.56 GB trace for `graph_interchange_codec`, which
8959	/// no remote will accept. zstd takes that to roughly 55 MB, and `zstd` is
8960	/// already a workspace dependency used for exactly this under AM-11.6.
8961	///
8962	/// The digest is taken over the DECOMPRESSED bytes, which diverges from
8963	/// AM-11.6 deliberately. AM-11.6 freezes the compressed artifact; here
8964	/// `trace_blake3` already means "digest of the trace this campaign produced",
8965	/// and keeping that meaning leaves every existing check saying exactly what it
8966	/// said before. It also survives a zstd upgrade: the attestation is over
8967	/// content, not over an encoding.
8968	fn read_evidence_bytes(path: &Utf8Path) -> Result<Vec<u8>> {
8969	    if path.extension() == Some("zst") {
8970	        let file = fs::File::open(path).with_context(|| format!("open {path}"))?;
8971	        zstd::decode_all(std::io::BufReader::new(file))
8972	            .with_context(|| format!("{path}: evidence is not valid zstd"))
8973	    } else {
8974	        fs::read(path).with_context(|| format!("read {path}"))
8975	    }
8976	}
