9042	/// The normative wording a requirement coordinate names, whitespace-normalized
9043	/// (AM-17.17).
9044	///
9045	/// A coordinate is DEFINED at exactly one site: a list item whose bold label
9046	/// opens with it (`- **D20.3 —** ...`), or, for a `## ` coordinate, that
9047	/// heading. The clause is the item and its continuation lines, up to the next
9048	/// item, blank line or heading; for a heading, the section up to the next `## `
9049	/// heading. Prose that merely mentions `D20.3` is not a definition, which
9050	/// `has_exact_coordinate_anchor` cannot tell apart.
9051	///
9052	/// Whitespace is collapsed so rewrapping a paragraph is not a change of meaning,
9053	/// while any change to a word is.
9054	fn requirement_clause(source: &str, coordinate: &str) -> Result<String> {
9055	    let lines: Vec<&str> = source.lines().collect();
9056	    let is_heading = coordinate.starts_with("## ");
9057	    let starts: Vec<usize> = lines
9058	        .iter()
9059	        .enumerate()
9060	        .filter(|(_, line)| {
9061	            if is_heading {
9062	                line.trim() == coordinate
9063	            } else {
9064	                let item = line.trim_start();
9065	                (item.starts_with("- **") || item.starts_with("* **"))
9066	                    && item[4..].strip_prefix(coordinate).is_some_and(|rest| {
9067	                        rest.chars()
9068	                            .next()
9069	                            .is_none_or(|ch| !coordinate_anchor_char(ch))
9070	                    })
9071	            }
9072	        })
9073	        .map(|(index, _)| index)
9074	        .collect();
9075	    anyhow::ensure!(
9076	        starts.len() == 1,
9077	        "coordinate {coordinate:?} has {} definition sites; it must have exactly one",
9078	        starts.len()
9079	    );
9080	    let start = starts[0];
9081	    let indent = |line: &str| line.len() - line.trim_start().len();
9082	    let item_indent = indent(lines[start]);
9083	    let mut end = start + 1;
9084	    while end < lines.len() {
9085	        let line = lines[end];
9086	        let trimmed = line.trim_start();
9087	        // A nested sub-item is part of the requirement it sits under; only an
9088	        // item at the definition's own depth or shallower begins another one.
9089	        let sibling_item =
9090	            (trimmed.starts_with("- ") || trimmed.starts_with("* ")) && indent(line) <= item_indent;
9091	        let stop = if is_heading {
9092	            line.starts_with("## ")
9093	        } else {
9094	            trimmed.is_empty() || trimmed.starts_with('#') || sibling_item
9095	        };
9096	        if stop {
9097	            break;
9098	        }
9099	        end += 1;
9100	    }
9101	    Ok(lines[start..end]
9102	        .join(" ")
9103	        .split_whitespace()
9104	        .collect::<Vec<_>>()
9105	        .join(" "))
9106	}
