9108	/// `(requirement id, digest)` for every packet requirement, computed by the
9109	/// same code that verifies them, for `haq requirement-digests`.
9110	///
9111	/// Reads the packet as plain JSON rather than through `Packet`: the struct
9112	/// requires `source_blake3`, and a tool that computes the binding cannot depend
9113	/// on the binding already being present.
9114	pub fn requirement_digests(root: &Utf8Path) -> Result<Vec<(String, String)>> {
9115	    let path = root.join("conformance/haqp/packet.json");
9116	    let packet: serde_json::Value =
9117	        serde_json::from_slice(&fs::read(&path).with_context(|| format!("read {path}"))?)
9118	            .with_context(|| format!("parse {path}"))?;
9119	    packet["requirements"]
9120	        .as_array()
9121	        .context("packet has no requirements array")?
9122	        .iter()
9123	        .map(|requirement| {
9124	            let id = requirement["id"]
9125	                .as_str()
9126	                .context("requirement without id")?;
9127	            let source = requirement["source"]
9128	                .as_str()
9129	                .with_context(|| format!("requirement {id} without source"))?;
9130	            let (file, coordinate) = source
9131	                .split_once(':')
9132	                .with_context(|| format!("requirement {id} source lacks coordinate"))?;
9133	            let text =
9134	                fs::read_to_string(root.join(file)).with_context(|| format!("read {file}"))?;
9135	            let clause = requirement_clause(&text, coordinate)
9136	                .with_context(|| format!("requirement {id}"))?;
9137	            Ok((
9138	                id.to_owned(),
9139	                blake3::hash(clause.as_bytes()).to_hex().to_string(),
9140	            ))
9141	        })
9142	        .collect()
9143	}
