9145	/// A requirement coordinate is an exact anchor, not a substring assertion.
9146	///
9147	/// Semantic anchors such as `D18.1` must not match `D18.10`; heading anchors
9148	/// use their complete trimmed Markdown heading (`## Exit gate`) so a generic
9149	/// word such as `exit` cannot accidentally satisfy a gate row.
9150	fn has_exact_coordinate_anchor(source: &str, coordinate: &str) -> bool {
9151	    let coordinate = coordinate.trim();
9152	    if coordinate.is_empty() {
9153	        return false;
9154	    }
9155	    if coordinate.starts_with("## ") {
9156	        return source.lines().any(|line| line.trim() == coordinate);
9157	    }
9158	    source.lines().any(|line| {
9159	        line.match_indices(coordinate).any(|(offset, _)| {
9160	            let before = line[..offset].chars().next_back();
9161	            let after = line[offset + coordinate.len()..].chars().next();
9162	            before.is_none_or(|ch| !coordinate_anchor_char(ch))
9163	                && after.is_none_or(|ch| !coordinate_anchor_char(ch))
9164	        })
9165	    })
9166	}
9167	
9168	fn coordinate_anchor_char(ch: char) -> bool {
9169	    ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '-')
9170	}
