9339	/// M17.5 F-05: a requirement mapped to one coarse end-to-end test is not
9340	/// covered. Every critical requirement must carry all five core evidence
9341	/// kinds, and fault-class requirements must additionally carry injected-fault
9342	/// and idempotent-recovery evidence.
9343	fn verify_evidence_coverage(packet: &Packet) -> Result<()> {
9344	    let known = CORE_EVIDENCE
9345	        .iter()
9346	        .chain(STATEFUL_EVIDENCE.iter())
9347	        .copied()
9348	        .collect::<BTreeSet<_>>();
9349	    let mut covered = BTreeMap::<&str, BTreeSet<&str>>::new();
9350	    for test in &packet.tests {
9351	        if test.evidence.is_empty() {
9352	            anyhow::bail!("{} declares no evidence kind", test.id);
9353	        }
9354	        for kind in &test.evidence {
9355	            if !known.contains(kind.as_str()) {
9356	                anyhow::bail!("{} declares unknown evidence kind {kind}", test.id);
9357	            }
9358	        }
9359	        for requirement in &test.requirements {
9360	            covered
9361	                .entry(requirement.as_str())
9362	                .or_default()
9363	                .extend(test.evidence.iter().map(String::as_str));
9364	        }
9365	    }
9366	    for requirement in &packet.requirements {
9367	        if !requirement.critical {
9368	            continue;
9369	        }
9370	        let have = covered
9371	            .get(requirement.id.as_str())
9372	            .cloned()
9373	            .unwrap_or_default();
9374	        let mut needed = CORE_EVIDENCE.to_vec();
9375	        if requirement.stateful || requirement.kind == "fault" {
9376	            needed.extend_from_slice(&STATEFUL_EVIDENCE);
9377	        }
9378	        let missing = needed
9379	            .into_iter()
9380	            .filter(|kind| !have.contains(kind))
9381	            .collect::<Vec<_>>();
9382	        if !missing.is_empty() {
9383	            anyhow::bail!(
9384	                "critical requirement {} ({}) is missing {} evidence",
9385	                requirement.id,
9386	                requirement.kind,
9387	                missing.join(", ")
9388	            );
9389	        }
9390	    }
9391	    Ok(())
9392	}
