  9295	            requirement.kind == expected.0
  9296	                && requirement.source == expected.1
  9297	                && requirement.critical == expected.2
  9298	                && requirement.stateful == expected.3,
  9299	            "requirement {} differs from closed authoritative registry",
  9300	            requirement.id
