  9304	    verify_test_registry(packet)?;
  9305	    verify_mutant_inventory(packet)?;
  9306	    verify_kill_concentration(packet)?;
  9307	    verify_canary_inventory(packet)?;
  9308	    verify_generated_inventory(packet)?;
