  9683	fn verify_mutant_inventory(packet: &Packet) -> Result<()> {
  9684	    if packet.mutants.len() != 65 {
  9685	        anyhow::bail!("mutant count must be 65, got {}", packet.mutants.len());
  9686	    }
  9687	    require_unique(packet.mutants.iter().map(|row| row.id.as_str()), "mutant")?;
  9688	    let requirement_ids = packet
  9689	        .requirements
  9690	        .iter()
  9691	        .map(|row| row.id.as_str())
  9692	        .collect::<BTreeSet<_>>();
  9693	    let mut by_family = BTreeMap::<&str, usize>::new();
  9694	    let mut by_operator = BTreeMap::<&str, usize>::new();
  9695	    for mutant in &packet.mutants {
  9696	        // M17.5 pass-2 #13: family/operator/source/disposition were free text,
  9697	        // so a fabricated inventory with invented labels was accepted whole.
  9698	        // Each must now name something this suite actually declares.
  9699	        if !MUTANT_FAMILIES.contains(&mutant.family.as_str()) {
  9700	            anyhow::bail!(
  9701	                "{} declares unknown mutation family {:?}; expected one of {:?}",
  9702	                mutant.id,
  9703	                mutant.family,
  9704	                MUTANT_FAMILIES
  9705	            );
  9706	        }
  9707	        if !MUTANT_OPERATORS.contains(&mutant.operator.as_str()) {
  9708	            anyhow::bail!(
  9709	                "{} declares unknown mutation operator {:?}; expected one of {:?}",
  9710	                mutant.id,
  9711	                mutant.operator,
  9712	                MUTANT_OPERATORS
  9713	            );
  9714	        }
  9715	        if !MUTANT_DISPOSITIONS.contains(&mutant.disposition.as_str()) {
  9716	            anyhow::bail!(
  9717	                "{} declares unknown disposition {:?}; expected one of {:?}",
  9718	                mutant.id,
  9719	                mutant.disposition,
  9720	                MUTANT_DISPOSITIONS
  9721	            );
  9722	        }
  9723	        let requirement = if mutant.requirement.trim().is_empty() {
  9724	            // Proposed inventories from before the coordinate contract used
  9725	            // source for requirement ID. Preserve that plan shape, but never
  9726	            // treat it as an evaluated coordinate (qualified gate below is
  9727	            // strict).
  9728	            mutant.source.as_str()
  9729	        } else {
  9730	            mutant.requirement.as_str()
  9731	        };
  9732	        if !requirement_ids.contains(requirement) {
  9733	            anyhow::bail!(
  9734	                "{} names requirement {:?}, which is not a declared requirement — a mutant must \
  9735	                 attack something the inventory claims to require",
  9736	                mutant.id,
  9737	                requirement
  9738	            );
  9739	        }
  9740	        if !mutant.source.starts_with("P1-R") && mutant.requirement.trim().is_empty() {
  9741	            anyhow::bail!(
  9742	                "{} source {:?} is a coordinate but requirement ID is missing",
  9743	                mutant.id,
  9744	                mutant.source
  9745	            );
  9746	        }
  9747	        if !mutant.requirement.trim().is_empty() {
  9748	            let (file, line) = mutant.source.rsplit_once(':').with_context(|| {
  9749	                format!(
  9750	                    "{} source must be exact file:line; source is not a declared requirement",
  9751	                    mutant.id
  9752	                )
  9753	            })?;
  9754	            let line: usize = line
  9755	                .parse()
  9756	                .with_context(|| format!("{} source line is not numeric", mutant.id))?;
  9757	            anyhow::ensure!(
  9758	                line > 0
  9759	                    && !file.is_empty()
  9760	                    && !file.starts_with('/')
  9761	                    && !file.split('/').any(|part| part == ".."),
  9762	                "{} source must be safe file:line",
  9763	                mutant.id
  9764	            );
  9765	        }
  9766	        if mutant.defect.trim().is_empty() {
  9767	            anyhow::bail!("{} describes no defect", mutant.id);
  9768	        }
  9769	        validate_disposition(mutant)?;
  9770	        *by_family.entry(mutant.family.as_str()).or_default() += 1;
  9771	        *by_operator.entry(mutant.operator.as_str()).or_default() += 1;
  9772	        if mutant.disposition == "predeclared" && mutant.killing_tests.is_empty() {
  9773	            anyhow::bail!("{} has no killing test", mutant.id);
  9774	        }
  9775	    }
  9776	    verify_mutation_plan_balance(&by_family, &by_operator)?;
  9777	    Ok(())
  9778	}
