  9780	/// ADR-0020 §3's shape rules for the plan: thirteen mutants per family, no
  9781	/// operator over a quarter of the denominator, and every named operator
  9782	/// present (blind pass 1 at 5fb1b57, A04).
  9783	fn verify_mutation_plan_balance(
  9784	    by_family: &BTreeMap<&str, usize>,
  9785	    by_operator: &BTreeMap<&str, usize>,
  9786	) -> Result<()> {
  9787	    const REQUIRED_OPERATORS: [&str; 13] = [
  9788	        "predicate-deletion",
  9789	        "predicate-inversion",
  9790	        "threshold-plus-one",
  9791	        "threshold-minus-one",
  9792	        "missing-enum-dispatch",
  9793	        "success-error-substitution",
  9794	        "stale-basis-acceptance",
  9795	        "wrong-holder-selection",
  9796	        "skipped-durable-transition",
  9797	        "disabled-crash-point",
  9798	        "ordering-nondeterminism",
  9799	        "oracle-short-circuit",
  9800	        "broadened-allow-list",
  9801	    ];
  9802	    for (family, count) in by_family {
  9803	        if *count != 13 {
  9804	            anyhow::bail!("family {family} mutant count must be 13, got {count}");
  9805	        }
  9806	    }
  9807	    for (operator, count) in by_operator {
  9808	        if *count > 16 {
  9809	            anyhow::bail!("operator {operator} supplies {count} mutants; max 16");
  9810	        }
