  9813	    // PRESENT, so dropping one entirely — broadened-allow-list has a single
  9814	    // mutant — left the plan short an operator ADR-0020 §3 names and nothing
  9815	    // said so. The list is the ADR's, closed.
  9816	    let missing = REQUIRED_OPERATORS
  9817	        .into_iter()
