121	///
122	/// SHAPE PROVISIONAL — the variant set transcribes the §22 bullet list
123	/// ("files and document roots, block boundaries, headings, lists, fences,
124	/// directives, embedded language regions, resource references"); Phase 1
125	/// grammar work (ADR pending, v4 §119) may reshape it freely.
126	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
127	#[serde(rename_all = "kebab-case")]
128	pub enum CoarseKind {
129	    /// A file or document root (v4 §22).
130	    DocumentRoot,
131	    /// A heading block (v4 §22).
132	    Heading,
133	    /// An ordinary paragraph-like block (v4 §22 "block boundaries").
134	    ParagraphLike,
135	    /// A list block (v4 §22).
136	    List,
137	    /// A fenced block (v4 §22).
138	    Fence,
139	    /// A directive block (v4 §22).
140	    Directive,
141	    /// An embedded-language region (v4 §9, §22).
142	    EmbeddedLanguage,
