12047	/// Hold the §5 exhaustiveness claim to the surface it actually covers.
12048	///
12049	/// Ruling of 2026-08-26 (M17.5 A05): for HAQP-1a, exhaustiveness is claimed
12050	/// over ILRP alone, every other durable transition is deferred to M17.9, and
12051	/// the split is declared in the packet rather than left implicit. Deciding
12052	/// which of the runtime's transitions are *registrable* boundaries is runtime
12053	/// design work; doing it here would either block 1a on Phase 1 or pass by
12054	/// picking a convenient definition, and ADR-0020 §3 forbids improvising
12055	/// qualification semantics.
12056	///
12057	/// What is enforced instead is that the disclosure stays true. A prose scope
12058	/// note rots the first time somebody adds a commit site — which is exactly the
12059	/// defect A05 found in the original unscoped claim — so every durable
12060	/// transition in tracked source must fall inside a declared in-scope subsystem
12061	/// or a declared deferred surface, with counts matching exactly. A new
12062	/// `txn.commit()` anywhere turns the packet red until it is either registered
12063	/// or disclosed.
12064	fn verify_crash_boundary_scope(root: &Utf8Path, packet: &Packet) -> Result<()> {
12065	    let declared = verify_crash_boundary_scope_shape(packet)?;
12066	    let measured = durable_transition_sites(root)?;
12067	    for (path, count) in &measured {
12068	        let Some(expected) = declared.get(path.as_str()) else {
12069	            anyhow::bail!(
12070	                "{path} performs {count} durable transition(s) and is in neither the in-scope \
12071	                 nor the deferred surface: ADR-0020 §5 exhaustiveness cannot be claimed over a \
12072	                 surface the packet has not surveyed. Register its boundaries or disclose it."
12073	            );
12074	        };
12075	        anyhow::ensure!(
12076	            expected == count,
12077	            "{path}: crash_boundary_scope declares {expected} durable transition(s), source has \
12078	             {count}. The disclosure is stale — a durable surface moved under a claim that says \
12079	             it was surveyed."
12080	        );
12081	    }
12082	    for path in declared.keys() {
12083	        anyhow::ensure!(
12084	            measured.contains_key(*path),
12085	            "{path}: crash_boundary_scope declares durable transitions that no longer exist in \
12086	             tracked source"
12087	        );
12088	    }
12089	    Ok(())
12090	}

