11978	/// The half of the scope claim that reads only the packet, returning the
11979	/// declared surface keyed by path.
11980	///
11981	/// Split from the source-measured half deliberately: `verify_inventory_repo` is
11982	/// exercised against synthetic trees that hold a packet and nothing else, and a
11983	/// check must read only inputs its caller actually has. Measuring source there
11984	/// would either fail on a tree that is not at fault or — the worse outcome —
11985	/// invite a "skip when there is no source" branch, which is how a gate silently
11986	/// degrades into passing everything.
11987	fn verify_crash_boundary_scope_shape(packet: &Packet) -> Result<BTreeMap<&str, usize>> {
11988	    let scope = &packet.crash_boundary_scope;
11989	    anyhow::ensure!(
11990	        !scope.in_scope.is_empty(),
11991	        "crash_boundary_scope.in_scope is empty: §5 exhaustiveness must be claimed over at \
11992	         least one subsystem, or the packet claims nothing"
11993	    );
11994	    anyhow::ensure!(
11995	        !scope.deferred_to.trim().is_empty(),
11996	        "crash_boundary_scope.deferred_to must name who closes the deferral"
11997	    );
11998	    anyhow::ensure!(
11999	        !scope.rationale.trim().is_empty(),
12000	        "crash_boundary_scope.rationale must state why the claim is bounded"
12001	    );
12002	
12003	    // A registered boundary outside every declared subsystem means the packet
12004	    // registers boundaries it has not claimed scope over.
12005	    for row in &packet.crash_boundaries {
12006	        let subsystem = row.boundary.split('/').next().unwrap_or_default();
12007	        anyhow::ensure!(
12008	            scope
12009	                .in_scope
12010	                .iter()
12011	                .any(|entry| entry.subsystem == subsystem),
12012	            "crash boundary {} is outside every declared in-scope subsystem",
12013	            row.boundary
12014	        );
12015	    }
12016	
12017	    let mut declared: BTreeMap<&str, usize> = BTreeMap::new();
12018	    for entry in &scope.in_scope {
12019	        // A blank subsystem would match no boundary while still reading as a
12020	        // claim; a blank path would name no surface. Checked on this side too,
12021	        // not only on `deferred`, so the two halves cannot drift apart.
12022	        anyhow::ensure!(
12023	            !entry.subsystem.trim().is_empty() && !entry.path.trim().is_empty(),
12024	            "an in-scope subsystem must name both a boundary prefix and a path"
12025	        );
12026	        anyhow::ensure!(
12027	            declared.insert(entry.path.as_str(), entry.sites).is_none(),
12028	            "{} is declared twice in crash_boundary_scope",
12029	            entry.path
12030	        );
12031	    }
12032	    for entry in &scope.deferred {
12033	        anyhow::ensure!(
12034	            !entry.reason.trim().is_empty(),
12035	            "{}: a deferred durable surface must say why it is deferred",
12036	            entry.path
12037	        );
12038	        anyhow::ensure!(
12039	            declared.insert(entry.path.as_str(), entry.sites).is_none(),
12040	            "{} is declared both in scope and deferred",
12041	            entry.path
12042	        );
