  349	fn verify_oracle_independence(root: &Utf8Path) -> Result<()> {
  350	    for (file, function, forbidden) in INDEPENDENT_ORACLES {
  351	        let path = root.join(file);
  352	        anyhow::ensure!(
  353	            path.is_file(),
  354	            "{file}: independent oracle {function} has no source file"
  355	        );
  356	        // The scanned body spans the crate, so the aliases must too: a `use`
  357	        // that renames a forbidden symbol in another module renames it for
  358	        // code that is now inside the body being judged.
  359	        let text = crate_sources(root, file)?;
  360	        // Blind pass 1 at aecb2ec7 (A10): only the oracle's own body was
  361	        // scanned, so `fn helper(x) { paragraph::parse(x) }` called from the
  362	        // oracle reached the production path through one hop and named
  363	        // nothing. The body is the transitive closure now: the oracle plus
  364	        // every function defined in the same file that it reaches.
  365	        anyhow::ensure!(
  366	            item_body(&text, function).is_some(),
  367	            "{file}: independent oracle {function} is not defined"
  368	        );
  369	        let body = oracle_reachable_body(&text, function);
  370	        // Blind pass 1 at aa00d41 (A02): the scan matched literal paths, so
  371	        // `use liminal_source::paragraph::parse as p; p(input)` named none of
  372	        // them. A `use` that renames a forbidden symbol makes its alias
  373	        // forbidden too, in this file.
  374	        let mut watched_words: Vec<String> = Vec::new();
  375	        let mut watched = forbidden
  376	            .iter()
  377	            .map(|s| (*s).to_owned())
  378	            .collect::<Vec<_>>();
  379	        for line in text.lines() {
  380	            for (symbol, alias) in use_aliases(line) {
  381	                if forbidden.iter().any(|watch| {
  382	                    watch.contains(&symbol) || symbol.contains(watch.trim_end_matches('('))
  383	                }) {
  384	                    // Blind pass 1 at 5fb1b57 (A02): only the call form was
  385	                    // watched, so `use ...::paragraph as prod;` followed by
  386	                    // `prod::parse(input)` named nothing. A module alias is
  387	                    // used with `::`, a function alias with `(`.
  388	                    watched.push(format!("{alias}("));
  389	                    watched.push(format!("{alias}::"));
  390	                    // Blind pass 1 at `aeed70f9` (A02): only the call and
  391	                    // module forms were watched, so `let q = p; q(input)`
  392	                    // reached the production path under a name the scan had
  393	                    // never heard of. The bare alias is watched as a WORD, so
  394	                    // handing it to anything at all is the signal.
  395	                    watched_words.push(alias);
  396	                }
  397	            }
  398	        }
  399	        for symbol in &watched {
