11911	fn durable_transition_sites(root: &Utf8Path) -> Result<BTreeMap<String, usize>> {
11912	    // Blind pass 1 at 612cbcc (A05): `inner.log.append(` is the store's durable
11913	    // append (P1-M022 deletes it) and was outside the census, so an append-based
11914	    // transition could move without the scope disclosure noticing.
11915	    // Blind pass 1 at f360e90 (A05): a direct `fs::rename` or `sync_all` is a
11916	    // durable transition with no marker call around it, so it escaped.
11917	    // Blind pass 1 at aa00d41 (A05): `use std::fs::rename as mv; mv(a, b)`
11918	    // named no marker. The durable symbols are matched by name, and a `use`
11919	    // that renames one adds its alias for that file.
11920	    const DURABLE_SYMBOLS: [&str; 6] = [
11921	        "commit",
11922	        "commit_if",
11923	        "append",
11924	        "sync_all",
11925	        "sync_data",
11926	        "rename",
11927	    ];
11928	    let listed = git_text(root, &["ls-files", "-z", "--", "crates"])?;
11929	    let mut sites = BTreeMap::new();
11930	    for name in listed.split('\0').filter(|name| !name.trim().is_empty()) {
11931	        if Utf8Path::new(name).extension() != Some("rs")
11932	            || name.starts_with("crates/liminal-xtask/")
11933	            || name.contains("/tests/")
11934	        {
11935	            continue;
11936	        }
11937	        let path = root.join(name);
11938	        // Never skip a tracked file we cannot read. Dropping it would delete
11939	        // its transitions from the measured surface, and the disclosure would
11940	        // then pass by describing a tree nobody managed to look at — the exact
11941	        // vacuity this check exists to prevent.
11942	        let text = fs::read_to_string(&path).with_context(|| {
11943	            format!(
11944	                "{name} is tracked but unreadable; the durable surface cannot be measured, and \
11945	                 a scope claim over a surface that was not read is worth nothing"
11946	            )
11947	        })?;
11948	        // A `use` that renames a durable symbol makes the alias a marker in
11949	        // this file: `use std::fs::rename as mv;` means `mv` is a rename.
11950	        let mut markers = DURABLE_SYMBOLS
11951	            .iter()
11952	            .map(|symbol| (*symbol).to_owned())
11953	            .collect::<Vec<_>>();
11954	        for line in text.lines() {
11955	            for (symbol, alias) in use_aliases(line) {
11956	                if DURABLE_SYMBOLS.contains(&symbol.as_str()) {
11957	                    markers.push(alias);
11958	                }
11959	            }
11960	        }
11961	        let count = text
11962	            .lines()
11963	            // An import declares a name; it performs no transition. Without
11964	            // this the aliasing `use` line counts as a durable call itself.
11965	            .filter(|line| {
11966	                let trimmed = line.trim_start();
11967	                !trimmed.starts_with("//") && !trimmed.starts_with("use ")
11968	            })
11969	            .map(|line| durable_symbol_hits(line, &markers))
11970	            .sum::<usize>();
11971	        if count > 0 {
11972	            sites.insert(name.to_owned(), count);
11973	        }
11974	    }
11975	    Ok(sites)
11976	}
