733	                "review markdown claims {value:?} while the packet is unqualified; only the \
734	                 flip may write a verdict, and it runs on a qualified packet"
735	            );
736	        }
737	    }
738	    for header in RENDERED_TABLES {
739	        let tables = markdown_tables(&text, header);
740	        anyhow::ensure!(
741	            !tables.is_empty(),
742	            "review markdown has no table {header:?}"
743	        );
744	        // The HEADER's width, not the first row's: the finding was a row with
745	        // surplus cells beneath a narrower header, which comparing rows to
746	        // each other would not see. Each table brings its own.
747	        for (width, rows) in tables {
748	            for row in rows {
749	                // Blind pass 1 at 9eca4f0 (A09): cell VALUES were checked but not
750	                // how many there were, so a row could carry surplus cells beneath
751	                // a narrower header and read as a different claim.
752	                anyhow::ensure!(
753	                    row.len() == width,
754	                    "review markdown table {header:?} has a row of {} cells under a {width}-cell \
755	                 header",
756	                    row.len()
757	                );
758	                for cell in row {
759	                    // Cells are markdown: an identifier is spelled in backticks.
760	                    let value = cell.trim().trim_matches('`').trim();
761	                    let renders_results = qualified && RESULT_BEARING_TABLES.contains(&header);
762	                    anyhow::ensure!(
763	                        renders_results || cell_claims_nothing(value) || declared.contains(value),
764	                        "review markdown table {header:?} claims {value:?}, which the unqualified \
765	                     packet does not declare; only the flip may write a result, and it runs \
766	                     on a qualified packet"
767	                    );
768	                }
769	            }
770	        }
771	    }
772	    Ok(())
773	}
